{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Asciminib, which shares the azetidinol and heteroaryl amide/urea-like polar framework with the query, has an absolute oral bioavailability of approximately 73% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Lemborexant, a heteroaromatic oral drug with fluorophenyl and amide functionality, has at least 87% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "MMV367, containing a fluorophenyl pyrrolidine amide and heteroaromatic core, has an estimated human oral bioavailability of 90%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Trovafloxacin, a fused heteroaromatic with a difluorophenyl group, has a mean absolute oral bioavailability of 87.6% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paliperidone, a heteroaromatic antipsychotic with a fluorophenyl-containing substituent, has an absolute oral bioavailability of 28% in healthy fasting volunteers, which is above the 20% threshold and therefore supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Lumateperone has an absolute oral bioavailability of approximately 4.4% in humans, which is contradictory to high F, but its tricyclic piperazine ketone structure is markedly dissimilar to the query and transfers poorly.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Most transferable experimental evidence points to high oral bioavailability: several structurally related heteroaromatic/urea-azetidinol drugs have human F values of 73-90%, and even the lower paliperidone value (28%) is above the 20% threshold. The only clearly low-F analogue, lumateperone (4.4%), is structurally distant. Therefore predict high, with low confidence due to low Morgan similarities and lack of direct query PK data.",
  "evidence_gaps": [
    "No direct human or animal pharmacokinetic data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (~0.21-0.23), limiting transferability.",
    "No metabolite identification or first-pass metabolism data for the query.",
    "One structurally closer analogue (compound 26) was only predicted at 23% F, near the threshold, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

